UPDATE participants SET payload = json_set(payload, '$.name', 'Adam', '$.initials', 'A', '$.sex', 'male', '$.sleepingPreferences.ownRoom', 'not-needed', '$.sleepingPreferences.ownBed', json('false'), '$.sleepingPreferences.shareDoubleWithParticipantId', 'jacob', '$.sleepingPreferences.acceptsSofaBed', json('false'), '$.sleepingPreferences.roomPreferences', json('["happy-to-share"]'), '$.sleepingPreferences.bedPreferences', json('[]'), '$.sleepingPreferences.shareWithParticipantIds', json('["jacob"]')) WHERE trip_id = 'demo' AND id = 'oliver';
UPDATE participants SET payload = json_remove(json_set(payload, '$.sex', 'male', '$.sleepingPreferences.ownBed', json('true'), '$.sleepingPreferences.acceptsSofaBed', json('false'), '$.sleepingPreferences.bedPreferences', json('["own-bed"]'), '$.sleepingPreferences.shareWithParticipantIds', json('[]')), '$.sleepingPreferences.shareDoubleWithParticipantId') WHERE trip_id = 'demo' AND id = 'alex';
UPDATE participants SET payload = json_set(payload, '$.sex', 'male', '$.sleepingPreferences.acceptsSofaBed', json('false')) WHERE trip_id = 'demo' AND id = 'conor';
UPDATE participants SET payload = json_set(payload, '$.sex', 'male', '$.sleepingPreferences.acceptsSofaBed', json('false'), '$.sleepingPreferences.bedPreferences', json('["own-bed"]')) WHERE trip_id = 'demo' AND id = 'hanah';
UPDATE participants SET payload = json_set(payload, '$.sex', 'female', '$.sleepingPreferences.ownRoom', 'not-needed', '$.sleepingPreferences.ownBed', json('false'), '$.sleepingPreferences.shareDoubleWithParticipantId', 'oliver', '$.sleepingPreferences.acceptsSofaBed', json('false'), '$.sleepingPreferences.roomPreferences', json('["happy-to-share"]'), '$.sleepingPreferences.bedPreferences', json('[]'), '$.sleepingPreferences.shareWithParticipantIds', json('["oliver"]')) WHERE trip_id = 'demo' AND id = 'jacob';
UPDATE trip_memberships SET display_name = 'Adam' WHERE trip_id = 'demo' AND participant_id = 'oliver';
